// Turns content/style/<slug>.md (the editable style file for each guide) into
// src/lib/guideStylesGenerated.ts, so the chat prompt can use it without
// reading the filesystem at runtime.
//   node scripts/gen-guide-styles.mjs          write
//   node scripts/gen-guide-styles.mjs --check  fail if the generated file is stale
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "content", "style");
const out = join(root, "src", "lib", "guideStylesGenerated.ts");

const styles = {};
for (const file of readdirSync(dir).filter((f) => f.endsWith(".md")).sort()) {
  const raw = readFileSync(join(dir, file), "utf8").replace(/\r\n/g, "\n");
  const body = raw.replace(/^---\n[\s\S]*?\n---\n/, "").trim();
  if (/[–—]/.test(body)) throw new Error(`${file}: contains an em or en dash`);
  styles[file.replace(/\.md$/, "")] = body;
}

const text =
  "// Generated by scripts/gen-guide-styles.mjs from content/style/*.md. Do not edit.\n" +
  `export const guideStyles: Record<string, string> = ${JSON.stringify(styles, null, 2)};\n`;

if (process.argv.includes("--check")) {
  const current = existsSync(out) ? readFileSync(out, "utf8").replace(/\r\n/g, "\n") : "";
  if (current !== text) {
    console.error("guideStylesGenerated.ts is stale. Run: npm run styles:generate");
    process.exit(1);
  }
  console.log(`guide styles in sync (${Object.keys(styles).length})`);
} else {
  writeFileSync(out, text);
  console.log(`wrote ${Object.keys(styles).length} guide style(s)`);
}
